import{c as o,$ as n,Q as s,j as i,g as e,o as r,n as c,m as l}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Accounts & Wallets","description":"Practical guide to managing cash reserves, bank cards, deposits, multi-currency accounts, and digital assets in OmniCraft ERP.","frontmatter":{"title":"Accounts & Wallets","description":"Practical guide to managing cash reserves, bank cards, deposits, multi-currency accounts, and digital assets in OmniCraft ERP.","datePublished":"2026-10-28","dateModified":"2026-11-26","order":15},"headers":[],"relativePath":"docs/spaces/moy-kapital/accounts.md","filePath":"docs/spaces/moy-kapital/accounts.md","lastUpdated":1795651200000}'),d={name:"docs/spaces/moy-kapital/accounts.md"},u={id:"accounts-wallets-liquid-capital-hub",tabindex:"-1"};function p(h,t,g,m,y,f){const a=n("DocIcon");return s(),i("div",null,[e("h1",u,[r(a,{name:"capital"}),t[0]||(t[0]=c(" Accounts & Wallets: Liquid Capital Hub ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#accounts-wallets-liquid-capital-hub","aria-label":'Permalink to "Accounts & Wallets: Liquid Capital Hub"'},"​",-1))]),t[2]||(t[2]=l('<p>The <strong>Accounts &amp; Wallets</strong> tab serves as the foundational liquid liquidity center in the My Capital workspace. Here you record all funds not actively committed to current workshop production cycles: cash reserves in safe boxes or wallets, debit cards, high-yield savings deposits, foreign currency holdings, and digital transactional assets.</p><p>Regularly updating account balances provides the empirical baseline for automated personal expense tracking via the capital balance delta method. Rather than logging every petty coffee or fuel purchase daily, you simply maintain accurate balances across primary accounts, allowing the system to reconcile changes against workshop revenue streams.</p><hr><h2 id="consolidated-liquidity-balance-and-currency-conversion" tabindex="-1">Consolidated Liquidity Balance and Currency Conversion <a class="header-anchor" href="#consolidated-liquidity-balance-and-currency-conversion" aria-label="Permalink to &quot;Consolidated Liquidity Balance and Currency Conversion&quot;">​</a></h2><p>The top banner of the screen displays the master craftsman&#39;s consolidated liquid capital:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Wallet Icon] TOTAL IN ACCOUNTS: $ 25,000.00</span></span></code></pre></div><p>This metric aggregates all registered accounts and automatically converts balances to your base accounting currency (USD by default, or your configured base currency).</p><p>For accounts denominated in the base currency, the conversion multiplier is permanently set to 1.00. For foreign currencies or stablecoins, balances are converted according to the following formula:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Currency Standard</span><div class="formula-heading">Foreign Currency Conversion to Base Currency</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Base Currency Equivalent</span><span class="math-op">=</span><span class="math-var">Native Account Balance</span><span class="math-op">×</span><span class="math-var">Exchange Rate to Base</span></div></div><div class="formula-card-bottom"><p>Exchange rates can be refreshed automatically via the centralized rate dialog or edited manually in account settings. When rates change, all converted balances update instantly.</p></div></div><hr><h2 id="prerequisites-for-setting-up-accounts" tabindex="-1">Prerequisites for Setting Up Accounts <a class="header-anchor" href="#prerequisites-for-setting-up-accounts" aria-label="Permalink to &quot;Prerequisites for Setting Up Accounts&quot;">​</a></h2><p>Before structuring your personal financial accounts, outline the following:</p><ol><li><strong>Base Accounting Currency:</strong> By default, the software uses Russian Rubles (<code>RUB</code>), to which foreign currency balances are converted;</li><li><strong>Registry of Financial Repositories:</strong> List your active debit cards, bank deposits, cash safes, and digital wallets with current balances;</li><li><strong>Exchange Rates:</strong> If holding assets in USD, EUR, or stablecoins, prepare current exchange rates for accurate total liquidity valuation.</li></ol><hr><h2 id="two-creation-modes-single-account-vs-bank-group" tabindex="-1">Two Creation Modes: Single Account vs. Bank Group <a class="header-anchor" href="#two-creation-modes-single-account-vs-bank-group" aria-label="Permalink to &quot;Two Creation Modes: Single Account vs. Bank Group&quot;">​</a></h2><p>Clicking the <strong>&quot;Add Account&quot;</strong> button in the upper-right corner opens a creation dialog with a mode selector:</p><ol><li><strong>&quot;Single Account&quot; Mode:</strong> a concise entry form for isolated items — cash in a workshop safe, petty cash envelopes, or a standalone credit card.</li><li><strong>&quot;Group / Bank / Vault&quot; Mode:</strong> a multi-currency container enabling you to register an entire financial institution with all its subsidiary products (checking account, foreign currency wallet, high-yield savings) in a single workflow.</li></ol><div class="tip custom-block"><p class="custom-block-title">Fast Multi-Account Registration</p><p>In Group mode, click <strong>&quot;Add another currency / account to group&quot;</strong>. You can dynamically attach any number of accounts with independent balances, currencies, and notes under the same bank umbrella.</p><p>Accounts entered in the same form are saved together. If one account fails to save, the whole batch is rolled back. Correct the details and save the form again.</p></div><hr><h2 id="account-parameter-specifications" tabindex="-1">Account Parameter Specifications <a class="header-anchor" href="#account-parameter-specifications" aria-label="Permalink to &quot;Account Parameter Specifications&quot;">​</a></h2><p>When creating or editing an account, the following parameters are configured:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Purpose &amp; Format</th><th style="text-align:left;">Example Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Account Name&quot;</strong></td><td style="text-align:left;">Clear title reflecting account role and utility</td><td style="text-align:left;"><em>Primary Debit Card</em>, <em>Workshop Safe Box</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Group (Bank)&quot;</strong></td><td style="text-align:left;">Name of the financial institution or physical container</td><td style="text-align:left;"><em>JPMorgan Chase</em>, <em>Cash Reserves</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Group Category&quot;</strong></td><td style="text-align:left;">Layout tag for grouping cards across the screen</td><td style="text-align:left;"><em>Banks &amp; Deposits</em>, <em>Crypto Wallets</em>, <em>Cash</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Account Type&quot;</strong></td><td style="text-align:left;">Liquidity classification tag</td><td style="text-align:left;"><em>Card</em>, <em>Deposit</em>, <em>Cash</em>, <em>E-Wallet</em>, <em>Crypto</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Currency&quot;</strong></td><td style="text-align:left;">Selection from standard currencies or custom ticker</td><td style="text-align:left;"><em>USD ($)</em>, <em>EUR (€)</em>, <em>GBP (£)</em>, <em>USDT</em>, <em>USDC</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Balance &amp; Rate&quot;</strong></td><td style="text-align:left;">Current actual balance and conversion rate to base currency</td><td style="text-align:left;"><em>$ 12,500.00</em>, <em>€ 1,000.00 (rate 1.08)</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Online Banking Link&quot;</strong></td><td style="text-align:left;">Direct web address to online banking for quick access</td><td style="text-align:left;"><code>https://secure.chase.com/</code></td></tr><tr><td style="text-align:left;"><strong>&quot;Notes&quot;</strong></td><td style="text-align:left;">Operational details (interest payment dates, maturity deadlines)</td><td style="text-align:left;"><em>Interest payout on the 15th of each month</em></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Customizing Types and Categories</p><p>Account types and group categories are fully user-configurable. Clicking the edit pencil icon next to either dropdown allows you to rename, create, or reorder categories to reflect your exact asset layout.</p></div><hr><h2 id="group-cards-and-workspace-organization" tabindex="-1">Group Cards and Workspace Organization <a class="header-anchor" href="#group-cards-and-workspace-organization" aria-label="Permalink to &quot;Group Cards and Workspace Organization&quot;">​</a></h2><p>Accounts sharing the same group name are automatically aggregated into structured cards:</p><ul><li><strong>Group Header:</strong> bank name, category badge, and active account count;</li><li><strong>Consolidated Group Balance:</strong> combined sum of all child accounts converted to base currency;</li><li><strong>Account Rows:</strong> line items displaying balance in native currency, base equivalent, and a direct online banking launcher;</li><li><strong>Quick Addition (+):</strong> button in the card header opening the creation dialog with this group pre-selected;</li><li><strong>Reordering (Up/Down Arrows):</strong> manually shifts card positions up or down;</li><li><strong>Manage Group (Pencil):</strong> comprehensive group management — renaming with cascading updates to child accounts, category reassignment, and reordering items inside the bank.</li></ul><hr><h2 id="view-modes-grid-tiles-vs-compact-stripes" tabindex="-1">View Modes: Grid Tiles vs. Compact Stripes <a class="header-anchor" href="#view-modes-grid-tiles-vs-compact-stripes" aria-label="Permalink to &quot;View Modes: Grid Tiles vs. Compact Stripes&quot;">​</a></h2><p>The toolbar provides a view layout toggle:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="7" height="7" x="3" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="14" rx="1"></rect><rect width="7" height="7" x="3" y="14" rx="1"></rect></svg></span><span><strong>&quot;Grid Tiles&quot; (Columns):</strong> Spacious card layout optimized for wide desktop screens, grouping cards by category across adaptive columns.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="8" x2="21" y1="6" y2="6"></line><line x1="8" x2="21" y1="12" y2="12"></line><line x1="8" x2="21" y1="18" y2="18"></line><line x1="3" x2="3.01" y1="6" y2="6"></line><line x1="3" x2="3.01" y1="12" y2="12"></line><line x1="3" x2="3.01" y1="18" y2="18"></line></svg></span><span><strong>&quot;Compact Stripes&quot; (List):</strong> Dense vertical accordion view for rapid balance audits without extensive scrolling.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Global Accordion Control</p><p>In Compact Stripes mode, the <strong>&quot;↕&quot;</strong> button on the toolbar expands or collapses all group cards simultaneously with a single click.</p></div><hr><h2 id="archiving-and-safe-deletion" tabindex="-1">Archiving and Safe Deletion <a class="header-anchor" href="#archiving-and-safe-deletion" aria-label="Permalink to &quot;Archiving and Safe Deletion&quot;">​</a></h2><p>When a bank card expires, a deposit matures, or an account is closed, you do not need to delete historical records — simply archive them:</p><ol><li>Open the account edit dialog or click the card action menu;</li><li>Select <strong>&quot;Archive&quot;</strong>. The account disappears from active views and ceases to impact current liquidity;</li><li>When all accounts inside a group are archived, the entire group card is cleanly hidden from the active workspace.</li></ol><div class="tip custom-block"><p class="custom-block-title">When to use the archive</p><p>Archive closed accounts whose records you want to keep in the list. For example, you can revisit a closed deposit after reconciliation.</p></div><p>To view hidden accounts, click the toolbar button with the <strong>&quot;Accounts archive&quot;</strong> tooltip. You can restore an account to the active list or confirm its removal. Removal hides the account from the archive and keeps saved balance snapshots in the database. An external assistant can remove an archived account in trusted mode.</p><hr><h2 id="troubleshooting-common-pitfalls" tabindex="-1">Troubleshooting &amp; Common Pitfalls <a class="header-anchor" href="#troubleshooting-common-pitfalls" aria-label="Permalink to &quot;Troubleshooting &amp; Common Pitfalls&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">What should I do if foreign currency balances fail to convert to base currency?</summary><div class="faq-content"><p>Inspect the &quot;Currency &amp; Exchange Rate&quot; field in the account editor. For foreign currencies or stablecoins, open the &quot;Exchange Rates&quot; dialog on the toolbar and update the rate against your base currency—converted equivalents recalculate instantly.</p></div></details><details class="faq-item"><summary class="faq-summary">How do I remove an active account from the list?</summary><div class="faq-content"><p>Archive the account first. Then open the archive and confirm removal.</p></div></details><details class="faq-item"><summary class="faq-summary">How can I merge multiple accounts from the same bank accidentally split into separate cards?</summary><div class="faq-content"><p>Open the account editor and select the identical bank name in the &quot;Group (Bank)&quot; field. The system automatically consolidates both accounts into a single organized banking institution card.</p></div></details></div>',41))])}const q=o(d,[["render",p]]);export{b as __pageData,q as default};
